import { expect, test } from '../../fixtures/billing';
import { PERIOD_END, projects } from '../../fixtures/testData';

test('BR-04 lines are converted to the customer\'s currency and rounded one by one, half away from zero, with tax worked out on the rounded line @critical', async ({ proposal, page }) => {
  await proposal.create(projects.norrskenGrid, PERIOD_END);

  await expect(page.locator('#proposal-currency')).toHaveText('SEK');
  await expect(page.locator('#proposal-rate')).toHaveText('11.4700');
  await expect(proposal.lines).toHaveCount(3);

  // 37.50 EUR x 11.47 = 430.125 SEK on each short call, rounded half away from zero.
  await expect(proposal.amountOf(1)).toHaveText('430.13');
  await expect(proposal.amountOf(2)).toHaveText('430.13');
  await expect(proposal.amountOf(3)).toHaveText('10,323.00');

  // Tax at 25.5% on the rounded line; 10,323.00 x 25.5% = 2,632.365.
  await expect(proposal.line(1).locator('.line-tax')).toHaveText('109.68');
  await expect(proposal.line(2).locator('.line-tax')).toHaveText('109.68');
  await expect(proposal.line(3).locator('.line-tax')).toHaveText('2,632.37');

  // Rounding the unrounded sum instead would give 11,183.25.
  await expect(proposal.subtotal).toHaveText('11,183.26');
  await expect(proposal.tax).toHaveText('2,851.73');
  await expect(proposal.total).toHaveText('14,034.99 SEK');

  page.once('dialog', (dialog) => dialog.accept());
  await page.locator('#delete-proposal').click();
  await expect(page.getByRole('status')).toHaveText('Proposal deleted.');
});
